body.script:
(function() {
    var KEY = 'playbook_banner_dismissed';
    var banner = document.getElementById('playbook-top-banner');
    if (!banner) return;
    var html = document.documentElement;

    function hide() {
        banner.style.display = 'none';
        html.classList.remove('has-playbook-banner');
    }
    function show() {
        banner.style.display = '';
        html.classList.add('has-playbook-banner');
    }

    try {
        if (sessionStorage.getItem(KEY) === '1') {
            hide();
            return;
        }
    } catch (e) {}

    show();

    banner.querySelector('.pb-banner-x').addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        hide();
        try { sessionStorage.setItem(KEY, '1'); } catch (err) {}
        if (typeof posthog !== 'undefined') {
            posthog.capture('playbook_banner_dismissed');
        }
    });
    banner.querySelector('.pb-banner-inner').addEventListener('click', function() {
        if (typeof posthog !== 'undefined') {
            posthog.capture('playbook_banner_clicked');
        }
    });
})();

(function() {
    // Two dismissal layers:
    //   - SESSION_KEY: soft X click. Hides for this browser session, reappears next session.
    //   - NEVER_KEY:   "Don't show again" link. Hides for 90 days.
    var SESSION_KEY = 'playbook_popup_session_dismissed';
    var NEVER_KEY = 'playbook_popup_never_show';
    var NEVER_DAYS = 90;
    var SCROLL_TRIGGER = 0.5;
    var SCROLL_DELAY_MS = 800;
    var RETRIGGER_DELAY_MS = 90000; // re-show after 90s if user soft-dismissed in same session

    var root = document.getElementById('playbook-popup-root');
    if (!root) return;

    function isNeverShow() {
        try {
            var v = localStorage.getItem(NEVER_KEY);
            if (!v) return false;
            var ageMs = Date.now() - parseInt(v, 10);
            return ageMs < NEVER_DAYS * 24 * 60 * 60 * 1000;
        } catch (e) { return false; }
    }
    function isSessionDismissed() {
        try { return sessionStorage.getItem(SESSION_KEY) === '1'; }
        catch (e) { return false; }
    }
    function markNeverShow() {
        try { localStorage.setItem(NEVER_KEY, String(Date.now())); } catch (e) {}
    }
    function markSessionDismissed() {
        try { sessionStorage.setItem(SESSION_KEY, '1'); } catch (e) {}
    }
    function clearSession() {
        try { sessionStorage.removeItem(SESSION_KEY); } catch (e) {}
    }

    var hasShown = false;
    function show() {
        if (isNeverShow()) return;
        hasShown = true;
        root.classList.add('is-visible');
        root.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
        if (typeof posthog !== 'undefined') {
            posthog.capture('playbook_popup_shown', { page_url: window.location.href });
        }
    }

    function hide() {
        root.classList.remove('is-visible');
        root.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
    }

    // Soft dismiss: closes for the session, but if user stays on page,
    // a retrigger timer will bring it back after RETRIGGER_DELAY_MS.
    function softDismiss() {
        markSessionDismissed();
        hide();
        hasShown = false;
        if (typeof posthog !== 'undefined') {
            posthog.capture('playbook_popup_soft_dismissed', { page_url: window.location.href });
        }
        // Re-arm: clear the session flag after delay so triggers fire again
        setTimeout(function() {
            clearSession();
        }, RETRIGGER_DELAY_MS);
    }

    // Hard dismiss: don't show for 90 days
    function neverShow() {
        markNeverShow();
        hide();
        if (typeof posthog !== 'undefined') {
            posthog.capture('playbook_popup_never_show', { page_url: window.location.href });
        }
    }

    if (isNeverShow()) return;
    // If session-dismissed, we wait for retrigger timer to clear it before showing again

    // Scroll trigger
    var scrollTimer = null;
    function onScroll() {
        if (hasShown || isSessionDismissed()) return;
        var scrolled = window.scrollY + window.innerHeight;
        var total = document.documentElement.scrollHeight;
        if (scrolled / total >= SCROLL_TRIGGER) {
            if (scrollTimer) return;
            scrollTimer = setTimeout(function() {
                if (!isSessionDismissed()) show();
                scrollTimer = null;
            }, SCROLL_DELAY_MS);
        }
    }

    window.addEventListener('scroll', onScroll, { passive: true });

    // Exit-intent trigger (desktop only)
    if (window.matchMedia('(min-width: 768px)').matches) {
        document.addEventListener('mouseleave', function(e) {
            if (e.clientY <= 0 && !hasShown && !isSessionDismissed()) { show(); }
        });
    }

    // Close handlers (X button + backdrop): soft dismiss
    root.querySelectorAll('[data-playbook-close]').forEach(function(el) {
        el.addEventListener('click', softDismiss);
    });

    // "Don't show again": hard dismiss (90 days)
    root.querySelectorAll('[data-playbook-never]').forEach(function(el) {
        el.addEventListener('click', neverShow);
    });

    // ESC to close (soft)
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && root.classList.contains('is-visible')) {
            softDismiss();
        }
    });

    // Form submit (relies on the same handler approach as the landing-page form)
    var form = root.querySelector('.playbook-popup-form');
    if (form) {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            var btn = form.querySelector('.playbook-submit-btn');
            var btnLabel = btn.querySelector('.btn-label');
            var msg = form.querySelector('.playbook-form-message');
            var original = btnLabel.textContent;
            btn.disabled = true;
            btnLabel.textContent = 'Sending...';
            msg.style.display = 'none';

            var fd = new FormData(form);

            fetch('https://autocalls.ai/voice-ai-playbook/submit', {
                method: 'POST',
                headers: { 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json' },
                body: fd,
            })
            .then(function(r) { return r.json().then(function(d) { return { ok: r.ok, data: d }; }); })
            .then(function(result) {
                if (result.ok) {
                    // Download right here; the email is only a copy.
                    var dl = result.data.download_url
                        ? 'Download the playbook'
                            + (result.data.deck_url ? 'Download the pitch deck' : '')
                        : '';
                    msg.innerHTML = '
' + result.data.message + '
' + dl + '';
                    msg.style.display = 'block';
                    msg.querySelectorAll('.playbook-download-btn').forEach(function (a) {
                        a.addEventListener('click', function () {
                            if (typeof posthog !== 'undefined') {
                                posthog.capture('playbook_download_clicked', { file: a.getAttribute('data-file'), page_url: window.location.href, source: 'popup' });
                            }
                        });
                    });
                    btnLabel.textContent = result.data.download_url ? 'Ready. Download below.' : 'Sent. Check your inbox.';
                    markNeverShow();
                    if (typeof posthog !== 'undefined') {
                        posthog.capture('playbook_popup_submitted', { page_url: window.location.href });
                    }
                    // Stay open while there is a download button to click.
                    if (!result.data.download_url) setTimeout(hide, 2200);
                } else {
                    var t = (result.data && result.data.message) || 'Error. Please try again.';
                    msg.innerHTML = '
' + t + '';
                    msg.style.display = 'block';
                    btn.disabled = false;
                    btnLabel.textContent = original;
                }
            })
            .catch(function() {
                msg.innerHTML = '
Network error. Try again.';
                msg.style.display = 'block';
                btn.disabled = false;
                btnLabel.textContent = original;
            });
        });
    }
})();
